import math

# Place a at angle 0. b at +/-t, c at +/-t. Require all pairwise angles equal t.
def ang(u, v):
    d = abs(u - v) % 360
    return min(d, 360 - d)

mags = {}
for t in range(0, 181):
    for sb in (1, -1):
        for sc in (1, -1):
            A, B, C = 0, sb * t, sc * t
            if ang(A, B) == t and ang(A, C) == t and ang(B, C) == t:
                x = 1 + 2 * math.cos(math.radians(B)) + 3 * math.cos(math.radians(C))
                y = 0 + 2 * math.sin(math.radians(B)) + 3 * math.sin(math.radians(C))
                m = math.hypot(x, y)
                mags.setdefault(t, set()).add(round(m, 9))

print("Valid configurations (angle in degrees -> |a+b+c|):", mags)
vals = sorted({m for s in mags.values() for m in s})
print("Possible magnitudes:", vals)
print("sqrt(3) =", round(math.sqrt(3), 9))

claimed = round(math.sqrt(3), 9)
if vals == [claimed]:
    print("CHECK PASS")
else:
    print("Claimed sqrt(3) is attainable but the angle-0 case gives 6 as well; answer is incomplete.")
    print("CHECK FAIL")
